/**
 * The calls to action of a post header: share and save side by side, one wide read button, or a wide read button
 * with share and save as icons.
 */
import { type JSX } from "solid-js";
import { Button, Group } from "../compose";
import { LucideIcon } from "../icons/LucideIcon";
import type { Post } from "../blocks/post-card.types";
import type { PostExtras, PostSplitLabels } from "../blocks/post-split.types";

export type PostActionsProps = {
  labels: PostSplitLabels;
  mode?: "pair" | "wide" | "icons";
};

export function PostActions({ labels, mode = "pair" }: PostActionsProps) {
  return (
    <>
      {((mode as string) === "pair") ? (
        <Group gap="2" class="flex-wrap" data-slot="post-actions">
          <Button variant="default" size="default" class="gap-2">
            <LucideIcon name="share-2" size={16} />
            {labels.share}
          </Button>
          <Button variant="outline" size="default" class="gap-2">
            <LucideIcon name="bookmark" size={16} />
            {labels.save}
          </Button>
        </Group>
      ) : (
        <Group gap="2" data-slot="post-actions">
          <Button variant="default" size="default" class="gap-2 flex-1">
            <LucideIcon name="book-open" size={16} />
            {labels.read}
          </Button>
          {((mode as string) === "icons") ? (
            <>
              <Button variant="outline" size="default" layout="icon" aria-label={labels.share}>
                <LucideIcon name="share-2" size={16} />
              </Button>
              <Button variant="outline" size="default" layout="icon" aria-label={labels.save}>
                <LucideIcon name="bookmark" size={16} />
              </Button>
            </>
          ) : null}
        </Group>
      )}
    </>
  );
}
